-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.post_scheduled_announcements()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a record;
begin
  for a in
    select * from public.scheduled_announcements
    where posted_at is null
      and cancelled_at is null
      and scheduled_for <= now()
    order by scheduled_for
  loop
    insert into public.messages (channel, channel_id, community_id, sender_id, body)
    values (coalesce(a.channel, 'announcements'), a.channel_id, a.community_id, a.created_by, a.body);

    update public.scheduled_announcements set posted_at = now() where id = a.id;
  end loop;
end;
$function$;
